  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 The Atom and Its Subatomic Particles$j$, $j${"readings": [{"title": "Psalm 147 (King James Version)", "url": "/portal/bible/Psalms/147"}], "body": "All matter is made of atoms, extremely small particles that are the building blocks of elements. Psalm 147:4 says, He telleth the number of the stars; he calleth them all by their names. The God who knows the stars also designed the tiny atoms of which they are made.\n\nOur understanding of the atom developed over time. John Dalton proposed that elements are made of tiny indivisible atoms and that atoms of different elements differ. J. J. Thomson discovered the electron, a tiny negative particle. Ernest Rutherford showed that most of an atom is empty space, with a small, dense, positive center called the nucleus. Niels Bohr described electrons moving in energy levels around the nucleus. The modern quantum model describes regions of space called orbitals where electrons are most likely to be found.\n\nAn atom has three main subatomic particles. A proton has a positive charge and is found in the nucleus. A neutron has no charge and is also in the nucleus. An electron has a negative charge and moves around the nucleus. Protons and neutrons each have a mass of about 1 atomic mass unit, while an electron has a very small mass, about one eighteen hundredth as much. The number of protons is the atomic number, and it identifies the element. In a neutral atom the number of electrons equals the number of protons.\n\nAn ion is an atom that has gained or lost electrons. Losing electrons makes a positive ion called a cation, and gaining electrons makes a negative ion called an anion.\n\nYour task: (1) Describe the charge and location of the proton, neutron and electron. (2) Explain what the atomic number tells you. (3) Explain how Rutherford discovered the nucleus.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Psalm 147:4 says, He telleth the number of the stars; he calleth them all by their names. The God who knows the stars also designed the tiny atoms of which they are made.\n\nNow watch this. Dalton said elements are made of atoms. Thomson discovered the electron. Rutherford showed that most of an atom is empty space with a small, dense, positive nucleus. Bohr described energy levels. The modern model uses orbitals, regions where electrons are likely to be.\n\nThree subatomic particles. The proton is positive and in the nucleus. The neutron has no charge and is in the nucleus. The electron is negative and moves around the nucleus. Protons and neutrons each have a mass of about 1 atomic mass unit. Electrons are far lighter. The number of protons is the atomic number and it identifies the element. A neutral atom has equal protons and electrons.\n\nAn ion has gained or lost electrons. A cation is positive. An anion is negative.\n\nYour task is to describe the three particles, explain the atomic number and explain Rutherford's discovery. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 The Atom and Its Subatomic Particles$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Isotopes and Atomic Mass$j$, $j${"readings": [{"title": "Matthew 10 (King James Version)", "url": "/portal/bible/Matthew/10"}], "body": "Every atom of a given element has the same number of protons, but the number of neutrons can differ. Atoms of the same element with different numbers of neutrons are called isotopes. Carbon always has 6 protons, but carbon 12 has 6 neutrons and carbon 14 has 8 neutrons. Isotopes of an element have nearly identical chemical properties but different masses. Some isotopes are radioactive.\n\nThe mass number is the total number of protons plus neutrons in the nucleus of one atom. To find the number of neutrons, subtract the atomic number from the mass number. An atom of chlorine with a mass number of 35 and an atomic number of 17 has 18 neutrons. Isotopes can be written with the element name and mass number, such as chlorine 35, or with symbols showing the mass number above and the atomic number below.\n\nThe atomic mass shown on the periodic table is a weighted average of the masses of an element's naturally occurring isotopes, measured in atomic mass units. If chlorine is about 76 percent chlorine 35 and about 24 percent chlorine 37, the average atomic mass is about 35.5. To calculate it, multiply each isotope's mass by its fractional abundance and add the results. Matthew 10:30 says, But the very hairs of your head are all numbered. Our Creator knows even the smallest details of what He has made.\n\nIsotopes have many uses. Carbon 14 helps date ancient organic materials, iodine isotopes are used in medicine for the thyroid, and cobalt 60 is used in some cancer treatments. These tools should be used wisely and for human good.\n\nYour task: (1) Define isotope. (2) Find the number of protons, neutrons and electrons in a neutral atom with atomic number 11 and mass number 23. (3) Calculate the average atomic mass of an element with 50 percent of an isotope of mass 10 and 50 percent of an isotope of mass 12.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Matthew 10:30 says, But the very hairs of your head are all numbered. Our Creator knows even the smallest details of what He has made.\n\nNow watch this. Every atom of an element has the same number of protons, but the number of neutrons can differ. Atoms of the same element with different neutrons are isotopes. Carbon 12 has 6 neutrons. Carbon 14 has 8 neutrons. Isotopes have nearly identical chemical properties but different masses.\n\nThe mass number is protons plus neutrons. To find neutrons, subtract the atomic number from the mass number. Chlorine 35 has 17 protons and 18 neutrons.\n\nThe atomic mass on the periodic table is a weighted average of the isotopes. Multiply each isotope's mass by its fractional abundance and add. Chlorine averages about 35.5.\n\nIsotopes have uses in dating, medicine and treatment. Use them wisely.\n\nYour task is to define isotope, count particles in sodium 23 and calculate an average atomic mass. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Isotopes and Atomic Mass$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Electron Arrangement and Electron Configuration$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Electrons are arranged around the nucleus in energy levels, also called shells. The first energy level holds up to 2 electrons, the second holds up to 8 in the simplest model, and higher levels hold more. Each level contains sublevels named s, p, d and f. An s sublevel holds up to 2 electrons, a p sublevel up to 6, a d sublevel up to 10 and an f sublevel up to 14. Electrons occupy regions called orbitals, and each orbital holds a maximum of 2 electrons.\n\nElectron configuration shows how electrons fill the sublevels. Three rules guide the filling. The Aufbau principle says electrons fill the lowest energy sublevels first. The Pauli exclusion principle says an orbital holds at most two electrons, and they must have opposite spins. Hund's rule says electrons spread out among orbitals of the same sublevel, one in each, before they pair up. The filling order starts 1s, 2s, 2p, 3s, 3p, 4s, 3d. Oxygen, with 8 electrons, has the configuration 1s2 2s2 2p4. Sodium, with 11 electrons, is 1s2 2s2 2p6 3s1.\n\nValence electrons are the electrons in the outermost energy level, and they determine how an atom bonds. Sodium has 1 valence electron, and oxygen has 6. Atoms tend to react in a way that gives them a full outer level, usually 8 electrons, which is called the octet rule. Noble gases already have full outer levels and rarely react.\n\nWhen atoms absorb energy, electrons can jump to higher levels. When they fall back, they release light of specific colors. This is why different elements glow with different colors in flame tests and in neon signs. Genesis 1:3 says, And God said, Let there be light: and there was light.\n\nYour task: (1) Write the electron configuration of nitrogen. (2) State how many valence electrons magnesium has. (3) Explain why different elements give off different colors of light.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Genesis 1:3 says, And God said, Let there be light: and there was light. Light is also the way atoms tell us about their electrons.\n\nNow watch this. Electrons are arranged in energy levels. Each level has sublevels s, p, d and f. An s holds 2, a p holds 6, a d holds 10 and an f holds 14. Each orbital holds up to 2 electrons.\n\nThree rules. Aufbau: fill the lowest energy first. Pauli: opposite spins in an orbital. Hund: spread out before pairing. Oxygen is 1s2 2s2 2p4. Sodium is 1s2 2s2 2p6 3s1.\n\nValence electrons are in the outermost level and determine bonding. Atoms tend to reach a full outer level of 8, the octet rule. Noble gases are already full.\n\nWhen electrons absorb energy they jump up. When they fall back they release light of specific colors. That is why flame tests and neon signs show different colors.\n\nYour task is to write the configuration of nitrogen, count magnesium's valence electrons and explain the colors. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Electron Arrangement and Electron Configuration$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 The Periodic Table and Periodic Trends$j$, $j${"readings": [{"title": "1 Corinthians 14 (King James Version)", "url": "/portal/bible/1Corinthians/14"}], "body": "The periodic table organizes the elements in order of increasing atomic number. Dmitri Mendeleev published an early version in 1869, arranging elements by properties and leaving gaps for elements not yet discovered. Rows are called periods, and columns are called groups or families. Elements in the same group have the same number of valence electrons and similar chemical properties. 1 Corinthians 14:33 says, For God is not the author of confusion, but of peace. The orderly pattern of the elements reflects the order of creation.\n\nElements are classified as metals, nonmetals and metalloids. Metals, on the left and center of the table, are generally shiny, good conductors of heat and electricity, malleable and ductile. Nonmetals, on the right, are generally dull, poor conductors and brittle as solids. Metalloids lie along a stair step line and have properties of both. Important families include the alkali metals in group 1, which are very reactive; the alkaline earth metals in group 2; the halogens in group 17, which are very reactive nonmetals; and the noble gases in group 18, which are unreactive.\n\nPeriodic trends are patterns across the table. Atomic radius, the size of an atom, decreases from left to right across a period and increases going down a group. Ionization energy, the energy needed to remove an electron, increases from left to right and decreases going down a group. Electronegativity, the tendency of an atom to attract electrons in a bond, increases from left to right and decreases going down a group, with fluorine the most electronegative. These trends result from the number of protons pulling on the electrons and the number of energy levels between the nucleus and the outer electrons.\n\nYour task: (1) Explain why elements in the same group behave alike. (2) Compare the properties of metals and nonmetals. (3) Predict which has a larger atomic radius, sodium or chlorine, and explain why.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, 1 Corinthians 14:33 says, For God is not the author of confusion, but of peace. The orderly pattern of the elements reflects the order of creation.\n\nNow watch this. The periodic table lists elements by atomic number. Mendeleev arranged elements by properties and left gaps for undiscovered ones. Rows are periods. Columns are groups. Elements in a group have the same number of valence electrons and similar properties.\n\nMetals are shiny, conduct heat and electricity, and are malleable and ductile. Nonmetals are dull and poor conductors. Metalloids have both. Group 1 alkali metals are very reactive. Group 17 halogens are reactive nonmetals. Group 18 noble gases are unreactive.\n\nTrends. Atomic radius decreases across a period and increases down a group. Ionization energy increases across and decreases down. Electronegativity increases across and decreases down. Fluorine is the most electronegative.\n\nYour task is to explain group behavior, compare metals and nonmetals and predict sodium versus chlorine size. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 The Periodic Table and Periodic Trends$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Atomic Structure and the Periodic Table$j$, $j${"prompt": "Write a report of at least 250 words on atoms and the periodic table. Use complete sentences and label each part. Psalm 147:4 says, He telleth the number of the stars; he calleth them all by their names.\n\nPart 1: Describe the charge, mass and location of protons, neutrons and electrons. Summarize how the models of Dalton, Thomson, Rutherford and Bohr improved our understanding of the atom.\nPart 2: Define atomic number, mass number and isotope. For a neutral atom with atomic number 20 and mass number 40, state the number of protons, neutrons and electrons. Explain how average atomic mass is found.\nPart 3: Write the electron configurations of carbon and sodium and identify the number of valence electrons in each. Explain the octet rule.\nPart 4: Describe periods, groups, metals, nonmetals and metalloids. Explain the trends in atomic radius, ionization energy and electronegativity across a period and down a group.\nPart 5: Explain how Psalm 147:4 and 1 Corinthians 14:33 encourage us as we study the order in creation.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 25 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Atomic Structure and the Periodic Table$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: He Calleth Them All by Their Names$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains in your own words why the periodic table is useful to scientists, (2) describes one element you use or depend on every day and what you know about it, (3) explains how it feels to study something too small to see and how that can build your faith or your curiosity, and (4) connects your answer to Psalm 147:4, Matthew 10:30 or 1 Corinthians 14:33. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it important that scientists change their models when new evidence appears? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: He Calleth Them All by Their Names$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: The Atom and Its Subatomic Particles$j$, $j${"questions": [{"q": "A particle in the nucleus with a positive charge is the:", "options": ["Anion", "Neutron", "Proton", "Electron"]}, {"q": "The atomic number equals the number of:", "options": ["Neutrons", "Electrons plus neutrons", "Orbitals", "Protons"]}, {"q": "Rutherford showed that an atom has:", "options": ["Evenly spread positive charge", "No electrons", "A small, dense, positive nucleus", "No empty space"]}, {"q": "An atom that loses electrons becomes a:", "options": ["Anion", "Cation", "Neutron", "Isotope"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Atom and Its Subatomic Particles$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,1}'::int[], array[$j$Protons are positive and in the nucleus.$j$,$j$The number of protons defines the element.$j$,$j$His gold foil experiment revealed the nucleus.$j$,$j$Losing negative charge leaves a positive ion.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Atom and Its Subatomic Particles$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Isotopes and Atomic Mass$j$, $j${"questions": [{"q": "Atoms of the same element with different numbers of neutrons are:", "options": ["Isotopes", "Compounds", "Ions", "Molecules"]}, {"q": "Mass number equals:", "options": ["Neutrons minus protons", "Protons plus neutrons", "Protons plus electrons", "Electrons only"]}, {"q": "An atom with atomic number 17 and mass number 35 has how many neutrons?", "options": ["17", "18", "52", "35"]}, {"q": "The atomic mass on the periodic table is a:", "options": ["Count of electrons", "Number of protons", "Charge of the atom", "Weighted average of isotope masses"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Isotopes and Atomic Mass$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,3}'::int[], array[$j$Isotopes differ only in neutron number.$j$,$j$Mass number counts nucleons.$j$,$j$35 minus 17 equals 18.$j$,$j$It accounts for the abundance of each isotope.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Isotopes and Atomic Mass$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Electron Arrangement and Electron Configuration$j$, $j${"questions": [{"q": "A p sublevel can hold up to how many electrons?", "options": ["6", "2", "14", "10"]}, {"q": "The electron configuration of oxygen is:", "options": ["1s2 2s2 2p4", "1s2 2s2 2p6", "1s2 2s4 2p2", "1s2 2s1 2p5"]}, {"q": "Electrons in the outermost energy level are called:", "options": ["Neutrons", "Isotopes", "Valence electrons", "Core electrons"]}, {"q": "Different elements show different flame colors because:", "options": ["They have no electrons", "Their nuclei burn", "Electrons release specific energies when falling to lower levels", "They are all the same"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Electron Arrangement and Electron Configuration$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,2}'::int[], array[$j$A p sublevel has three orbitals holding 6 electrons.$j$,$j$Oxygen has 8 electrons.$j$,$j$Valence electrons determine bonding.$j$,$j$Energy level differences are unique to each element.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Electron Arrangement and Electron Configuration$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: The Periodic Table and Periodic Trends$j$, $j${"questions": [{"q": "Columns of the periodic table are called:", "options": ["Shells", "Groups", "Isotopes", "Periods"]}, {"q": "Group 18 elements are called the:", "options": ["Halogens", "Metalloids", "Noble gases", "Alkali metals"]}, {"q": "Going from left to right across a period, atomic radius generally:", "options": ["Stays the same", "Increases", "Decreases", "Doubles"]}, {"q": "The most electronegative element is:", "options": ["Iron", "Helium", "Sodium", "Fluorine"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Periodic Table and Periodic Trends$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,3}'::int[], array[$j$Groups share valence electron counts.$j$,$j$The noble gases are unreactive.$j$,$j$More protons pull electrons closer.$j$,$j$Fluorine attracts electrons most strongly.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Periodic Table and Periodic Trends$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Atomic Structure and the Periodic Table$j$, $j${"questions": [{"q": "The charge of an electron is:", "options": ["Neutral", "Positive", "Negative", "Variable"]}, {"q": "The number of protons in an atom is its:", "options": ["Atomic number", "Mass number", "Isotope number", "Valence number"]}, {"q": "Carbon 14 has how many neutrons?", "options": ["8", "14", "6", "20"]}, {"q": "The maximum number of electrons in an orbital is:", "options": ["6", "10", "8", "2"]}, {"q": "Sodium has how many valence electrons?", "options": ["1", "2", "11", "8"]}, {"q": "Elements in the same group have similar properties because they have the same number of:", "options": ["Neutrons", "Energy levels", "Valence electrons", "Isotopes"]}, {"q": "Ionization energy generally increases:", "options": ["With more energy levels", "Down a group", "From right to left", "Across a period from left to right"]}, {"q": "Which group contains very reactive nonmetals?", "options": ["Transition metals", "Alkali metals", "Noble gases", "Halogens"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Atomic Structure and the Periodic Table$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,3,0,2,3,3}'::int[], array[$j$Electrons carry a negative charge.$j$,$j$Atomic number identifies the element.$j$,$j$14 minus 6 equals 8.$j$,$j$Each orbital holds two electrons with opposite spins.$j$,$j$Sodium is in group 1.$j$,$j$Valence electrons control chemical behavior.$j$,$j$Stronger attraction makes electrons harder to remove.$j$,$j$The halogens in group 17 are reactive nonmetals.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Atomic Structure and the Periodic Table$j$ on conflict (item_id) do nothing;
